<?php require dirname(__DIR__).'/includes/app.php';
$admins=read_json('admins.json',[]); if(!$admins){header('Location:/admin/setup.php');exit;}
$error=''; if(!is_admin()&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$u=(string)($_POST['username']??'');$pw=(string)($_POST['password']??'');foreach($admins as $a){if(hash_equals((string)$a['username'],$u)&&password_verify($pw,(string)$a['password'])){session_regenerate_id(true);$_SESSION['admin']=$u;header('Location:/admin/');exit;}}$error='Invalid username or password.';}
if(!is_admin()):?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="/admin/admin.css"></head><body class="login-body"><form class="login-card" method="post"><div class="admin-logo">GB</div><h1>Admin Login</h1><p>Manage Galindos Builders projects and navigation.</p><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Username<input name="username" required></label><label>Password<input type="password" name="password" required></label><button>Sign In</button><a href="/">← Return to website</a></form></body></html><?php exit; endif;
$notice=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
if($action==='add_project'){$list=read_json('projects.json',[]);$name=trim((string)$_POST['name']);$slug=slugify($name);foreach($list as $x)if(($x['slug']??'')===$slug)$slug.='-'.time();$imgs=save_uploaded_images($_FILES['images']??[]);$list[]=['id'=>bin2hex(random_bytes(8)),'slug'=>$slug,'name'=>$name,'location'=>trim((string)($_POST['location']??'')),'category'=>trim((string)($_POST['category']??'Framing')),'status'=>trim((string)($_POST['status']??'Completed')),'description'=>trim((string)($_POST['description']??'')),'featured'=>isset($_POST['featured']),'images'=>$imgs,'created_at'=>date(DATE_ATOM)];write_json('projects.json',$list);$notice='Project added.';}
if($action==='delete_project'){$id=(string)$_POST['id'];$list=read_json('projects.json',[]);$list=array_values(array_filter($list,fn($x)=>($x['id']??'')!==$id));write_json('projects.json',$list);$notice='Project deleted.';}
if($action==='add_tab'){$list=read_json('tabs.json',tabs());$label=trim((string)$_POST['label']);$list[]=['id'=>slugify($label).'-'.time(),'label'=>$label,'url'=>trim((string)$_POST['url']),'visible'=>true,'sort'=>(int)($_POST['sort']??50)];write_json('tabs.json',$list);$notice='Navigation tab added.';}
if($action==='save_tabs'){$list=read_json('tabs.json',tabs());foreach($list as &$t){$id=$t['id'];$t['label']=trim((string)($_POST['label'][$id]??$t['label']));$t['url']=trim((string)($_POST['url'][$id]??$t['url']));$t['sort']=(int)($_POST['sort'][$id]??$t['sort']);$t['visible']=isset($_POST['visible'][$id]);}unset($t);write_json('tabs.json',$list);$notice='Navigation updated.';}
if($action==='delete_tab'){$id=(string)$_POST['id'];$list=array_values(array_filter(read_json('tabs.json',tabs()),fn($x)=>($x['id']??'')!==$id));write_json('tabs.json',$list);$notice='Tab deleted.';}}
$items=projects();$nav=tabs();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Galindos Builders Admin</title><link rel="stylesheet" href="/admin/admin.css"></head><body><aside><div class="admin-logo">GB</div><h2>Galindos Builders</h2><a href="#projects">Projects</a><a href="#new">Add Project</a><a href="#tabs">Navigation Tabs</a><a href="/" target="_blank">View Website ↗</a><a href="/admin/logout.php">Sign Out</a></aside><main class="admin-main"><header><div><small>WEBSITE ADMIN</small><h1>Content Dashboard</h1></div><span>Signed in as <?=e($_SESSION['admin'])?></span></header><?php if($notice):?><div class="success"><?=e($notice)?></div><?php endif;?><section class="stats"><article><strong><?=count($items)?></strong><span>Projects</span></article><article><strong><?=count($nav)?></strong><span>Navigation Tabs</span></article><article><strong><?=count(array_filter($items,fn($p)=>!empty($p['featured'])))?></strong><span>Featured</span></article></section><section class="panel" id="new"><h2>Add a Project / Job</h2><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_project"><label>Custom Job Name<input name="name" required placeholder="Example: Maple Avenue Townhomes"></label><label>Location<input name="location" placeholder="Baltimore, Maryland"></label><label>Category / Tab<input name="category" list="categories" placeholder="Wood Framing"><datalist id="categories"><option>Wood Framing</option><option>Commercial</option><option>Residential</option><option>Multi-Family</option><option>In Progress</option></datalist></label><label>Status<input name="status" placeholder="Completed"></label><label class="full">Project Description<textarea name="description" rows="5"></textarea></label><label class="full">Project Photos<input type="file" name="images[]" accept="image/jpeg,image/png,image/webp,image/gif" multiple></label><label class="check full"><input type="checkbox" name="featured" checked> Feature this project on the home page</label><button>Add Project</button></form></section><section class="panel" id="projects"><h2>Projects</h2><div class="table-wrap"><table><thead><tr><th>Job</th><th>Category</th><th>Location</th><th>Photos</th><th></th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><b><?=e($p['name'])?></b></td><td><?=e($p['category'])?></td><td><?=e($p['location'])?></td><td><?=count($p['images']??[])?></td><td><form method="post" onsubmit="return confirm('Delete this project?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_project"><input type="hidden" name="id" value="<?=e($p['id'])?>"><button class="danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel" id="tabs"><h2>Custom Navigation Tabs</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_tabs"><div class="table-wrap"><table><thead><tr><th>Visible</th><th>Label</th><th>URL</th><th>Order</th><th></th></tr></thead><tbody><?php foreach($nav as $t):$id=$t['id'];?><tr><td><input type="checkbox" name="visible[<?=e($id)?>]" <?=!empty($t['visible'])?'checked':''?>></td><td><input name="label[<?=e($id)?>]" value="<?=e($t['label'])?>"></td><td><input name="url[<?=e($id)?>]" value="<?=e($t['url'])?>"></td><td><input type="number" name="sort[<?=e($id)?>]" value="<?=e((string)$t['sort'])?>"></td><td><button type="submit" name="action" value="delete_tab" formaction="/admin/delete-tab.php" disabled title="Use delete button below">—</button></td></tr><?php endforeach;?></tbody></table></div><button>Save Navigation</button></form><hr><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value=